   RuntimeException rejected=null;source.armed=true;try{repo.save(actor,meeting,UUID.randomUUID().toString(),request,UUID.randomUUID().toString());}catch(RuntimeException failed){rejected=failed;}finally{source.armed=false;}LocalActionOwnerCheck.check(source.inserted&&rejected!=null,"Actual meeting_info_revision INSERT must execute");boolean intended=false;for(Throwable cause=rejected;cause!=null;cause=cause.getCause())if(cause instanceof SQLException&&cause.getMessage().equals("LOCAL_QUALIFICATION_AFTER_MEETING_INFO_INSERT"))intended=true;LocalActionOwnerCheck.check(intended&&before.equals(snapshot(j,meeting)),"Exact post-insert rollback of info/roster/grants/root/receipt/audit/outbox required");System.out.println(new ObjectMapper().writeValueAsString(Map.of("pass",true,"meetingId",meeting,"genuineFactoriesAndSharedInstances",true,"actualInfoInsertExecuted",true,"ambientCommandRejected",true,"zeroSnapshotChanges",true)));
